const MANJUSHA_INFO={id:"manjusha-painting",title:"Manjusha Painting & Bihula–Bishari Folk Art",originRegion:"Bhagalpur, Bihar (Anga Region)",eraOrigin:"Ancient Anga Mahajanapada (c. 7th Century CE)",giTagStatus:"Geographical Indication (GI) Certified",ritualTradition:"Bihula–Bishari Puja (Manasa Puja)",signatureColors:"Red, Green & Yellow",specialElement:"Temple-shaped ritual caskets known as Manjusha boxes",quickStats:[{label:"GI Tag Certified",value:"Bhagalpur, Bihar",icon:"🏷️"},{label:"Origin Region",value:"Anga Mahajanapada",icon:"🏛️"},{label:"Ritual Tradition",value:"Bihula–Bishari Puja",icon:"🐍"},{label:"Signature Colors",value:"Red, Green & Yellow",icon:"🎨"},{label:"Backdrop Styles",value:"Kala, Peela & Lal",icon:"🖌️"},{label:"Traditional Medium",value:"Cloth & Natural Pigments",icon:"🧵"}]},MATERIALS_AND_METHOD=[{step:1,title:"Canvas & Casket Preparation",description:"Artisans coat hand-woven cotton cloth or temple-shaped bamboo, jute and paper caskets with tamarind-seed gum paste to create a smooth painting surface."},{step:2,title:"Natural Color Extraction",description:"Pigments are drawn from turmeric, indigo, lampblack and vermilion, and mixed with gum arabic to create the vivid red, green and yellow folk palette."},{step:3,title:"The Bamboo Kalam",description:"Fine-pointed bamboo pens trace bold black outlines, with every figure drawn in a single unbroken stroke — a hallmark discipline of Manjusha art."},{step:4,title:"Ritual Backdrops",description:"The background is painted in one of the three auspicious shades — black (Kala Manjusha), yellow (Peela Manjusha) or red (Lal Manjusha)."},{step:5,title:"Narrative Panels",description:"Episodes of the Bihula–Bishari story are painted in sequence around the casket and scrolls, each panel moving the tale from darkness to light."}],TRADITIONAL_MOTIFS=[{name:"Bishari Devi (Snake Goddess)",description:"The central serpent-goddess figure whose blessings shield the household from snakebite — the heart of the entire Bihula–Bishari legend."},{name:"Bihula & Lakshindra",description:"The devoted couple at the centre of the myth, shown on their wedding couch and upon the night-long raft journey down the Ganga."},{name:"Serpent Coils & Hoods",description:"Swirling snakes and cobra hoods dominate the compositions, earning Manjusha the name 'snake paintings' among early western viewers."},{name:"The Manjusha Casket",description:"The temple-shaped box with eight pillars — the ritual object that gives the art its name and around which the painted narrative unfolds."},{name:"Lotus, Fish & Tortoise",description:"Riverine auspicious symbols of the Anga countryside that frame the scenes of Bihula's journey."},{name:"Sun, Mango & Flower",description:"Marks of fertility, prosperity and renewal that complete the folk vocabulary of the paintings."}],MYTH_STORIES=[{title:"The Devotion of Bihula",icon:"🌙",story:"On the night of her wedding, the serpents of the snake-goddess Bishari struck Bihula's husband Lakshindra. Refusing to accept her fate, the merchant's daughter carried his body on a raft down the Ganga through the long night, singing and offering worship, until the goddess relented and restored him to life. Her unshakeable devotion is the soul of every Manjusha painting."},{title:"The Bishari Puja",icon:"🐍",story:"During the month of Shravan, families of the Anga region create Manjusha paintings and display them on ritual caskets to honour Bishari — locally known as Manasa Devi — seeking her protection from snakes and her blessings for the home. The paintings are created anew each season, keeping the tradition alive year after year."},{title:"The Manjusha Box",icon:"🎁",story:"The temple-shaped manjusha, built of bamboo, jute and paper with eight pillars, is the ritual centre of the puja. Covered with white paper and painted with the Bihula–Bishari narrative, it transforms a simple casket into a moving shrine that carries the mythology of the Anga region into every home."}],ARTISAN_COMMUNITY={title:"Artisans of the Anga Region",description:"Historically practised by the Kumbhakar (potter) and Malakar (gardener) communities around the Bishari puja, Manjusha art once faced near extinction. Today a new generation of painters — including state-awardee artists such as Ulupi Kumari of Bhagalpur — has revived the tradition, carrying the Bihula–Bishari story onto canvas, cloth and paper."},GALLERY_IMAGES=[{url:"https://upload.wikimedia.org/wikipedia/en/4/44/Manjusha.jpg",caption:"Manjusha box used in the Snake Festival — the temple-shaped ritual casket that gives the art its name.",category:"Ritual"},{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Manjusha_boat_art.jpg",caption:"Manjusha boat art depicting Bihula's night-long raft journey down the Ganga with the fallen Lakshindra.",category:"Mythology"},{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Manjusha_drawing.jpg",caption:"Traditional Manjusha drawing with bold black outlines and the characteristic single-stroke figures.",category:"Artwork"},{url:"https://commons.wikimedia.org/wiki/Special:FilePath/Manjusha_Painting_of_Map_of_Bihar.png",caption:"Contemporary Manjusha painting of the map of Bihar, showing how the folk idiom travels beyond ritual.",category:"Contemporary"}],REFERENCES=[{text:"Geographical Indications Registry — Manjusha Art (GI certified, Bhagalpur, Bihar).",link:"https://ipindia.gov.in"},{text:"Sahapedia (2021). Manjusha Art of Eastern Bihar.",link:"https://www.sahapedia.org/manjusha-art-eastern-bihar"},{text:"Bihar Museum — Bihula–Bishari Folklore (Manjusha) by Ulupi Kumari.",link:"https://www.biharmuseum.org/bihulla-vishari-folklore-manjusha-ulupi-kumari/"},{text:"Handicrafts India (Office of the Development Commissioner for Handicrafts) — Manjusha Art.",link:"https://handicrafts.nic.in"}];"undefined"!=typeof module&&module.exports&&(module.exports={MANJUSHA_INFO:MANJUSHA_INFO,MATERIALS_AND_METHOD:MATERIALS_AND_METHOD,TRADITIONAL_MOTIFS:TRADITIONAL_MOTIFS,MYTH_STORIES:MYTH_STORIES,ARTISAN_COMMUNITY:ARTISAN_COMMUNITY,GALLERY_IMAGES:GALLERY_IMAGES,REFERENCES:REFERENCES});